type User struct {
	Name     string `json:"name"`
	Email    string `json:"email,omitempty"`
	Password string `json:"-"`
	internal int    `json:"internal"`
}

// Marshal produces:
//   {"name":"raz"}
//
// Email  - omitted, empty and tagged omitempty
// Password - never emitted, tagged "-"
// internal - invisible: unexported, tag ignored entirely

type S struct {
	N    int
	Tags []string
}

a := S{N: 1, Tags: []string{"x"}}
b := a           // copies both fields

b.N = 2
b.Tags[0] = "y"

fmt.Println(a.N)       // 1  - independent
fmt.Println(a.Tags[0]) // "y"  - SHARED

type Base struct{ ID string }

func (b Base) Describe() string { return "base " + b.ID }

type Job struct {
	Base            // embedded: no field name
	Name string
}

j := Job{Base: Base{ID: "7"}, Name: "sync"}
j.ID          // "7"        - promoted field
j.Describe()  // "base 7"   - promoted method
j.Base.ID     // the long form, always available

type A struct {
	sync.Mutex        // embedded: A.Lock() is PUBLIC
	n int
}

type B struct {
	mu sync.Mutex     // named: callers cannot lock it
	n  int
}
